def start_workers(out_q, err_q, chunks, lock):
    tasks = [Process(target=worker, args=(out_q, err_q, chunk, lock))
             for chunk in chunks]
    for task in tasks:
        task.start()
    return collect(out_q, err_q, tasks, lock)

